export class APIError extends Error{constructor(status,message,code='request_rejected'){super(message);this.status=status;this.code=code;}}
export const need=(ok,status,message,code)=>{if(!ok)throw new APIError(status,message,code);};
export const validId=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(x);
