const sql=(env,q,...args)=>env.DB.prepare(q).bind(...args);
const one=(env,q,...args)=>sql(env,q,...args).first();
const rows=async(env,q,...args)=>(await sql(env,q,...args).all()).results;
const run=(env,q,...args)=>sql(env,q,...args).run();
