export async function bodyBytes(request,limit){const advertised=request.headers.get('content-length');if(advertised)need(/^\d+$/.test(advertised)&&Number(advertised)<=limit,413,'Body exceeds limit');need(request.body,400,'Request body required');const reader=request.body.getReader(),parts=[];let size=0;try{while(true){const {value,done}=await reader.read();if(done)break;size+=value.byteLength;need(size<=limit,413,'Body exceeds limit');parts.push(value);}}catch(e){await reader.cancel().catch(()=>{});throw e;}const out=new Uint8Array(size);let at=0;for(const part of parts){out.set(part,at);at+=part.length;}return out;}
