async function rate(env,bucket,cap,window){const t=now();const value=await one(env,'INSERT INTO limits(bucket,start,count) VALUES(?,?,1) ON CONFLICT(bucket) DO UPDATE SET count=CASE WHEN start+?<? THEN 1 ELSE count+1 END,start=CASE WHEN start+?<? THEN ? ELSE start END RETURNING count',bucket,t,window,t,window,t,t);need(value.count<=cap,429,'Request limit reached');}
