const bearer=request=>request.headers.get('authorization')?.match(/^Bearer (.+)$/)?.[1]||'';
async function device(request,env){const found=await one(env,'SELECT *,id AS device_id FROM devices WHERE token=? AND revoked=0 AND expires>?',hash(bearer(request)),now());need(found,401,'Device credential expired or revoked');await run(env,'UPDATE devices SET last_seen=? WHERE id=?',now(),found.id);return found;}
const owner=(request,env,mutate)=>bearer(request)?device(request,env):session(request,env,mutate);
async function deviceOwned(env,deviceId,user){const d=await one(env,'SELECT * FROM devices WHERE id=? AND user_id=? AND revoked=0 AND expires>?',deviceId,user,now());need(d,404,'Device unavailable');return d;}
async function jobOwned(env,jobId,user,native=false){const j=await one(env,'SELECT * FROM jobs WHERE id=? AND user_id=?',jobId,user.user_id);need(j&&(!native||j.device_id===user.device_id),404,'Job unavailable');return j;}
export function downloadTicket(env,job,deviceId,expires=Math.floor(now()+300)){need(env.DOWNLOAD_SECRET&&env.DOWNLOAD_SECRET.length>=32&&!env.DOWNLOAD_SECRET.startsWith('REPLACE'),503,'Download signing secret is unconfigured');return `${expires}.${createHmac('sha256',env.DOWNLOAD_SECRET).update(`${deviceId}:${job.id}:${job.sha256}:${expires}`).digest('hex')}`;}
async function cleanup(env,jobId){let cursor;do{const listed=await env.UPLOADS.list({prefix:`jobs/${jobId}/`,limit:1000,cursor});if(listed.objects.length)await env.UPLOADS.delete(listed.objects.map(o=>o.key));cursor=listed.truncated?listed.cursor:undefined;}while(cursor);await run(env,'DELETE FROM chunks WHERE job_id=?',jobId);await run(env,'UPDATE jobs SET cleanup_pending=0 WHERE id=?',jobId);}
async function discardJobObject(env,jobId,key){
 const referenced=await one(env,'SELECT 1 FROM chunks WHERE object_key=? UNION ALL SELECT 1 FROM jobs WHERE ready_key=? LIMIT 1',key,key);
 if(!referenced)await env.UPLOADS.delete(key);
 const current=await one(env,'SELECT status FROM jobs WHERE id=?',jobId);
 if(current&&FINAL.includes(current.status)){await run(env,'UPDATE jobs SET cleanup_pending=1 WHERE id=?',jobId);await cleanup(env,jobId);}
}
async function cleanupTom(env,userId=null,conversationId=null,deviceId=null){
 while(true){const pending=await rows(env,"SELECT id,payload_key FROM tom WHERE status='deleting' AND (? IS NULL OR user_id=?) AND (? IS NULL OR conversation_id=?) AND (? IS NULL OR device_id=?) LIMIT 100",userId,userId,conversationId,conversationId,deviceId,deviceId);if(!pending.length)return;
  for(const turn of pending){let cursor='';while(true){const children=await rows(env,'SELECT id,object_key FROM tom_illustrations WHERE parent_request_id=? AND id>? ORDER BY id LIMIT 100',turn.id,cursor);if(!children.length)break;for(const child of children){await run(env,"UPDATE tom_illustrations SET status='canceled',updated=? WHERE id=?",now(),child.id);await env.UPLOADS.delete(child.object_key||`tom-illustrations/${child.id}/image.png`);cursor=child.id;}}if(turn.payload_key)await env.UPLOADS.delete(turn.payload_key);await run(env,"DELETE FROM tom WHERE id=? AND status='deleting'",turn.id);}
 }
}
async function enqueue(env,jobId,kind){await run(env,'INSERT OR IGNORE INTO outbox(id,kind,created) VALUES(?,?,?)',jobId,kind,now());try{await env.WORK.send({id:jobId,kind});await run(env,'DELETE FROM outbox WHERE id=?',jobId);}catch{/* Durable outbox is retried by scheduled handler. */}}
