async function content(request,env,job,user){need(['waiting for device','transferring'].includes(job.status)&&job.expires>now(),410,'Relay content unavailable');const t=request.headers.get('x-download-token')||'',expires=Number(t.split('.')[0]);need(Number.isInteger(expires)&&expires>now()&&expires<=now()+301&&secureEqual(t,downloadTicket(env,job,user.device_id,expires)),403,'Download access expired or invalid');let start=0,end=job.size-1,status=200;const range=request.headers.get('range');if(range){const match=/^bytes=(\d+)-(\d*)$/.exec(range);need(match,416,'Only one forward byte range supported');start=Number(match[1]);end=match[2]?Number(match[2]):end;need(Number.isSafeInteger(start)&&Number.isSafeInteger(end)&&start>=0&&start<=end&&end<job.size,416,'Invalid byte range');status=206;}const value=await env.UPLOADS.get(job.ready_key,{range:{offset:start,length:end-start+1}});need(value,410,'Relay object missing');await run(env,"UPDATE jobs SET status='transferring',updated=? WHERE id=? AND status IN ('waiting for device','transferring')",now(),job.id);return new Response(value.body,{status,headers:{'Content-Type':job.format==='pdf'?'application/pdf':'application/epub+zip','Content-Length':String(end-start+1),'Accept-Ranges':'bytes','Cache-Control':'no-store','X-Content-SHA256':job.sha256,ETag:`"${job.sha256}"`,...(status===206?{'Content-Range':`bytes ${start}-${end}/${job.size}`}:{})}});}
